  }, "\uD639\uC740 \uBE60\uB974\uAC8C, \uC801\uC740 \uBD80\uBD84\uB9CC \uAC1C\uC120\uD560 \uC218 \uC788\uC5B4\uC11C \uADF8\uB7F0 \uC870\uCE58\uAC00 \uD544\uC694\uC5C6\uB294\uAC00?")), mdx("p", null, "\uAE30\uC220 \uBD80\uCC44 \uCCAD\uC0B0\uC774\uB098 \uD50C\uB7AB\uD3FC \uC131\uACA9\uC758 \uAC1C\uC120\uC744 \uC704\uD574 \uACF5\uD1B5 \uAD6C\uD604\uCCB4\uB97C \uC0AC\uC6A9\uCC98\uC5D0\uC11C \uD2B9\uC815 \uBC29\uC2DD\uC73C\uB85C \uB9C8\uC774\uADF8\uB808\uC774\uC158 \uD574\uC57C\uD558\uB294 \uACBD\uC6B0\uAC00 \uC788\uB2E4. \uC774\uB7F0 \uC131\uD5A5\uC758 \uC791\uC5C5\uC740 \uAC00\uB054 \uD50C\uB7AB\uD3FC \uB2F4\uB2F9\uC790\uAC00 \uD2B9\uC815 \uAD6C\uD604\uCCB4\uB4E4\uC744 \uC62C\uBC14\uB978 \uC720\uC2A4\uCF00\uC774\uC2A4\uB85C \uBC14\uAFD4\uB193\uC74C\uACFC \uB3D9\uC2DC\uC5D0 \uB2E4\uB978 \uC81C\uD488 \uD55C\uCF20\uC5D0\uC11C\uB294 \uC774\uBBF8 \uC798\uBABB\uB41C \uC720\uC2A4\uCF00\uC774\uC2A4\uAC00 \uACC4\uC18D \uC7AC\uC0DD\uC0B0\uB41C\uB2E4."), mdx("p", null, "\uAC1C\uC120\uACFC \uB9DD\uCE68\uC774 \uB3D9\uC2DC\uC5D0 \uC77C\uC5B4\uB098\uB294 \uAC83\uC774\uB2E4. \uC774\uB7F0 \uACBD\uC6B0\uC5D0\uB294 \uB9C8\uC774\uADF8\uB808\uC774\uC158\uC744 \uC2DC\uC791\uD558\uAE30 \uC804\uC5D0 \uC798\uBABB\uB41C \uC720\uC2A4\uCF00\uC774\uC2A4\uB97C \uB9B0\uD2B8\uB8F0\uC774\uB098 CI\uC5D0\uC11C \uAE68\uC9C0\uAC8C \uD558\uB294 \uB4F1 \uC2DC\uC2A4\uD15C\uC5D0\uC11C \uAC80\uCD9C\uD558\uC9C0 \uC54A\uC73C\uBA74 \uC798\uBABB\uB41C \uC720\uC2A4\uCF00\uC774\uC2A4\uB294 \uACC4\uC18D \uC7AC\uC0DD\uC0B0\uB418\uACE0 \uB9C8\uC774\uADF8\uB808\uC774\uC158\uC758 \uC644\uB8CC \uC2DC\uC810\uB3C4 \uB2A6\uCDB0\uC9C4\uB2E4."), mdx("p", null, "\uB9C8\uC774\uADF8\uB808\uC774\uC158 \uC791\uC5C5\uC744 \uC9C1\uC811 \uC218\uD589\uD558\uB294 \uAC83\uC744 \uC77C\uC885\uC758 \uACF5\uACA9, \uC798\uBABB\uB41C \uC720\uC2A4\uCF00\uC774\uC2A4\uAC00 \uBC1C\uC0DD\uD558\uC9C0 \uC54A\uB3C4\uB85D \uAC1C\uBC1C \uD504\uB85C\uC138\uC2A4\uC5D0\uC11C \uC7A1\uB294 \uAC83\uC744 \uC77C\uC885\uC758 \uC218\uBE44\uB85C \uBCF4\uBA74, \uC218\uBE44\uB97C \uBA3C\uC800 \uD574\uB193\uACE0 \uACF5\uACA9\uC744 \uD574\uC57C \uD558\uB294 \uACBD\uC6B0\uAC00 \uC788\uB2E4. \uB193\uCE58\uBA74 \uB9D0\uADF8\uB300\uB85C \uAE68\uC9C4 \uB3C5\uC5D0 \uBB3C \uBD93\uAE30\uAC00 \uB41C\uB2E4."), mdx("p", null, "\uADF8\uB7EC\uB098 \uB9C8\uC774\uADF8\uB808\uC774\uC158\uC774 \uD544\uC694\uD55C \uC720\uC2A4\uCF00\uC774\uC2A4\uAC00 \uD2B9\uC815 \uBD80\uBD84\uC5D0 \uAD6D\uD55C\uB418\uC5B4 \uC810\uC9C4\uC801\uC73C\uB85C \uC9C4\uD589\uD560 \uC218 \uC788\uAC70\uB098, \uBAA8\uB178\uB808\uD3EC \uB4F1\uC758 \uD658\uACBD\uC5D0\uC11C \uC6D0\uC790\uC801 \uCEE4\uBC0B\uC73C\uB85C \uB9C8\uC774\uADF8\uB808\uC774\uC158\uC744 \uBE60\uB974\uACE0 \uAC04\uACB0\uD788 \uC9C4\uD589\uD560 \uC218 \uC788\uB2E4\uBA74 \uC218\uBE44\uD560 \uC2DC\uAC04\uC5D0 \uACF5\uACA9\uBD80\uD130 \uD558\uB294\uAC8C \uB354 \uD6A8\uC728\uC801\uC778 \uC77C \uC9C4\uD589 \uBC29\uC2DD\uC77C \uC218 \uC788\uB2E4. \uAC1C\uC120\uACFC \uB9DD\uCE68\uC774 \uB3D9\uC2DC\uC5D0 \uC77C\uC5B4\uB098\uB294 \uC0C1\uD669\uC744 \uC608\uC0C1\uD574\uBCFC \uB54C, \uAC1C\uC120\uC758 \uC18D\uB3C4\uAC00 \uB9DD\uCE68\uC758 \uC18D\uB3C4\uB97C \uCDA9\uBD84\uD788 \uCD94\uC6D4\uD560 \uC218 \uC788\uB2E4\uBA74 \uC5ED\uC2DC \uC218\uBE44\uB294 \uD544\uC694\uC5C6\uB2E4."), mdx("p", null, "\uC218\uBE44 \uC790\uCCB4\uAC00 \uAC1C\uBC1C\uC758 \uBD88\uD3B8\uD568\uC744 \uC57C\uAE30\uD560 \uC218 \uC788\uAE30 \uB54C\uBB38\uC5D0 \uC9C4\uD589\uD558\uB824\uB294 \uC218\uBE44\uAC00 \uB3D9\uB8CC \uAC1C\uBC1C\uC790\uB4E4\uC5D0\uAC8C \uB0A9\uB4DD \uAC00\uB2A5\uD55C \uC218\uC900\uC778\uC9C0 \uD639\uC740 \uC591\uD574\uB97C \uAD6C\uD558\uACE0 \uBD88\uD3B8\uD568\uC744 \uAC10\uC218\uD574\uC57C\uB9CC \uD558\uB294 \uC0C1\uD669\uC778\uC9C0 \uD3C9\uAC00\uD574\uBCF4\uB294 \uAC83\uB3C4 \uAF2D \uD544\uC694\uD55C \uACFC\uC815\uC774\uB2E4."), mdx("p", null, "\uACF5\uC218 \uC804\uD658\uC5D0 \uC788\uC5B4 \uC5B4\uB5A4 \uC804\uB7B5\uC744 \uC9DC\uACE0 \uC5B4\uB5BB\uAC8C \uC811\uADFC\uD558\uBA74 \uC88B\uC744\uC9C0 \uB9CE\uC774 \uC0DD\uAC01\uD574\